  };
  webframp.tmux.enable = true;
  webframp.zsh.enable = true;

  # Linux-specific defaults (can be overridden by hosts)
  webframp.tmux.terminal = lib.mkIf pkgs.stdenv.hostPlatform.isLinux "tmux-256color";
